package daisyui

import _ "embed"

// Safelist is the Tailwind v4 stylesheet fragment (a list of
// `@source inline(...)` directives) naming every class templ-ui components
// can render. Tailwind never scans the Go module cache and many daisyUI
// modifiers are assembled at runtime, so consuming applications must feed
// this into their CSS build; `go run github.com/geoffjay/templ-ui/cmd/templ-ui
// safelist -o <file>` writes it at the version pinned in go.mod. The file is
// generated by `bun run safelist` in templ-ui.
//
//go:embed safelist.css
var Safelist string
